import 'dart:math' as math;

import 'ayanamsa.dart';
import 'civil_time.dart';
import 'graha/graha_table.dart';
import 'julian_day.dart';
import 'moon.dart';
import 'sun.dart';

/// HYA-450 (Wave 1 graha engine, PR-A): the five visible grahas
/// (Mercury, Venus, Mars, Jupiter, Saturn) from the vendored VSOP87D
/// planetary theory (graha/graha_table.dart, generated by
/// tools/sweph/graha_build_table.py - Mercury, Venus, Earth, Mars,
/// Jupiter, Saturn; the Earth sections feed the geocentric subtraction
/// because the legacy vsop87d_earth.dart carries only the solar
/// channel's L series).
///
/// Pipeline (Meeus, Astronomical Algorithms ch. 32/33 conventions):
/// heliocentric VSOP87D L, B, R -> rectangular -> Earth pulled out of
/// the Earth-Moon barycentre by removing the Moon's geocentric vector
/// (mass fraction 0.012150585; the ELP mean-of-date and VSOP87D
/// dynamical-of-date frames match by construction) -> geometric
/// geocentric vector -> three light-time iterations (c =
/// 173.1446326846693 AU/day) -> first-order stellar aberration (the
/// vector normalization is the tangential projection) -> tropical
/// ecliptic longitude/latitude of date. Nutation is NOT applied (a
/// named ~1.1 arcsec sidereal-class contributor: the Swiss apparent
/// channel carries it, the sidereal difference largely cancels it -
/// see tools/sweph/graha_crosscheck.py). Sidereal = tropical minus
/// ayanamsaBase (TT domain, source delta 0.0 - the publisher profiles
/// compose on top exactly as everywhere else in the engine).
///
/// Accuracy receipts: the fresh JPL Horizons fixture
/// (test/fixtures/graha_horizons_2026.json, schema
/// nmiti-graha-horizons/1 - 49 daily instants per planet plus 1-hour
/// Mercury/Venus station refinements, geocentric apparent observer
/// ecliptic lon/lat) gates the tropical channels at 15 arcsec in
/// test/graha_test.dart, and tools/sweph/graha_crosscheck.py scores
/// the sidereal channels against Swiss Ephemeris in CI at provisional
/// 120/30 arcsec bands.

/// Mercury's index into every graha API ([kGrahaNames] order).
const int kGrahaMercury = 0;

/// Venus's index.
const int kGrahaVenus = 1;

/// Earth's index (the geocentric subtraction body; not a graha).
const int kGrahaEarth = 2;

/// Mars's index.
const int kGrahaMars = 3;

/// Jupiter's index.
const int kGrahaJupiter = 4;

/// Saturn's index.
const int kGrahaSaturn = 5;

/// Canonical body order of the vendored table and every public API:
/// Mercury, Venus, Earth, Mars, Jupiter, Saturn (VSOP87D file order).
const List<String> kGrahaNames = <String>[
  'mercury',
  'venus',
  'earth',
  'mars',
  'jupiter',
  'saturn',
];

/// Moon-to-(Earth+Moon) mass fraction: Earth = EMB - fraction *
/// (Moon - Earth), the standard pull-out of the Earth from the
/// Earth-Moon barycentre.
const double _moonMassFraction = 0.012150585;

/// Speed of light in AU/day (the light-day constant).
const double _lightSpeedAuPerDay = 173.1446326846693;

const double _auKm = 149597870.7;
const double _radPerDeg = math.pi / 180.0;
const double _degPerRad = 180.0 / math.pi;

/// Apparent geocentric position of a graha: tropical of date with
/// light-time and stellar aberration applied, plus the base-ayanamsa
/// sidereal longitude. Nutation is intentionally not applied (see the
/// library comment - the Swiss channel carries it inside its bands).
class GrahaPosition {
  /// Tropical ecliptic longitude of date, degrees in [0, 360).
  final double tropicalLongitudeDeg;

  /// Tropical ecliptic latitude of date, degrees.
  final double tropicalLatitudeDeg;

  /// Geocentric astrometric distance, AU.
  final double distanceAu;

  /// Base-ayanamsa sidereal longitude, degrees in [0, 360).
  final double siderealLongitudeDeg;

  const GrahaPosition({
    required this.tropicalLongitudeDeg,
    required this.tropicalLatitudeDeg,
    required this.distanceAu,
    required this.siderealLongitudeDeg,
  });
}

double _norm360(double deg) => deg % 360.0;

/// One body-variable of the vendored VSOP87D table: the six T^0..T^5
/// sections in flat [kGrahaTerms] order, tau in thousands of Julian
/// years, radians (AU in the R variables).
double _vsop87(int body, int variable, double tau) {
  final int secStart = body * 18 + (variable - 1) * 6;
  int cursor = 0;
  for (int s = 0; s < secStart; s++) {
    cursor += kGrahaSectionCounts[s];
  }
  double total = 0.0;
  double tauPow = 1.0;
  for (int power = 0; power < 6; power++) {
    final int n = kGrahaSectionCounts[secStart + power];
    double sum = 0.0;
    for (int t = 0; t < n; t++) {
      final int i = cursor * 3;
      sum += kGrahaTerms[i] *
          math.cos(kGrahaTerms[i + 1] + kGrahaTerms[i + 2] * tau);
      cursor++;
    }
    total += tauPow * sum;
    tauPow *= tau;
  }
  return total;
}

/// Heliocentric rectangular position of [body] at [jdTt], AU.
List<double> _heliocentricAu(int body, double jdTt) {
  final double tau = (jdTt - 2451545.0) / 365250.0;
  final double lon = _vsop87(body, 1, tau);
  final double lat = _vsop87(body, 2, tau);
  final double r = _vsop87(body, 3, tau);
  final double cb = math.cos(lat);
  return <double>[
    r * cb * math.cos(lon),
    r * cb * math.sin(lon),
    r * math.sin(lat),
  ];
}

/// Heliocentric Earth at [jdTt]: the VSOP87D Earth-Moon barycentre
/// minus the Moon's geocentric vector scaled by the mass fraction.
/// The ELP geometric moon is mean-of-date, the same frame VSOP87D
/// dynamical-of-date uses, so the subtraction is frame-consistent.
List<double> _earthHeliocentricAu(double jdTt) {
  final emb = _heliocentricAu(kGrahaEarth, jdTt);
  final moon = moonPosition(jdTt);
  final double rMoon = moon.distanceKm / _auKm;
  final double lon = moon.longitudeDeg * _radPerDeg;
  final double lat = moon.latitudeDeg * _radPerDeg;
  final double cb = math.cos(lat);
  return <double>[
    emb[0] - _moonMassFraction * rMoon * cb * math.cos(lon),
    emb[1] - _moonMassFraction * rMoon * cb * math.sin(lon),
    emb[2] - _moonMassFraction * rMoon * math.sin(lat),
  ];
}

double _norm3(List<double> v) =>
    math.sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);

/// Apparent geocentric position of [body] at [jdUt] (civil UT; the
/// engine converts to TT internally). Receipts: Horizons fixture gate
/// at 15 arcsec (test/graha_test.dart), Swiss sidereal scoreboard in
/// CI (tools/sweph/graha_crosscheck.py).
GrahaPosition grahaPosition(int body, double jdUt) {
  final double jdTt = jdTtFromJdUt(jdUt);
  final earth = _earthHeliocentricAu(jdTt);
  // Light time: iterate the geometric (downgraded) distance; three
  // passes converge far below the microarcsecond class.
  var geo = <double>[0.0, 0.0, 0.0];
  double lightDays = 0.0;
  for (int i = 0; i < 3; i++) {
    final p = _heliocentricAu(body, jdTt - lightDays);
    geo = <double>[p[0] - earth[0], p[1] - earth[1], p[2] - earth[2]];
    lightDays = _norm3(geo) / _lightSpeedAuPerDay;
  }
  final double dist = _norm3(geo);
  // First-order stellar aberration: apparent direction = astrometric
  // unit vector + Earth velocity/c, renormalized (the normalization is
  // the tangential projection). Central difference over one day.
  final earthBefore = _earthHeliocentricAu(jdTt - 0.5);
  final earthAfter = _earthHeliocentricAu(jdTt + 0.5);
  final double ax = geo[0] / dist +
      (earthAfter[0] - earthBefore[0]) / _lightSpeedAuPerDay;
  final double ay = geo[1] / dist +
      (earthAfter[1] - earthBefore[1]) / _lightSpeedAuPerDay;
  final double az = geo[2] / dist +
      (earthAfter[2] - earthBefore[2]) / _lightSpeedAuPerDay;
  final double norm = math.sqrt(ax * ax + ay * ay + az * az);
  final double lonDeg = _norm360(math.atan2(ay, ax) * _degPerRad);
  final double latDeg = math.asin(az / norm) * _degPerRad;
  final double siderealDeg = _norm360(lonDeg - ayanamsaBase(jdTt));
  return GrahaPosition(
    tropicalLongitudeDeg: lonDeg,
    tropicalLatitudeDeg: latDeg,
    distanceAu: dist,
    siderealLongitudeDeg: siderealDeg,
  );
}

/// Wrap-safe apparent daily longitude rate, degrees per day, from the
/// +/- 0.5 day central difference (the ayanamsa drift is ~0.14
/// arcsec/day and never changes the sign).
double grahaLongitudeRateDegPerDay(int body, double jdUt) {
  final double before = grahaPosition(body, jdUt - 0.5).tropicalLongitudeDeg;
  final double after = grahaPosition(body, jdUt + 0.5).tropicalLongitudeDeg;
  double d = after - before;
  if (d > 180.0) d -= 360.0;
  if (d < -180.0) d += 360.0;
  return d;
}

/// Whether [body] is retrograde (negative apparent longitude rate) at
/// [jdUt].
bool grahaIsRetrograde(int body, double jdUt) =>
    grahaLongitudeRateDegPerDay(body, jdUt) < 0.0;

/// The retrograde station nearest [nearJdUt] (a rate sign change in
/// the +/- [windowDays] window, refined by 60 bisections), or null if
/// the body stays direct through the window. Receipts: the Mercury and
/// Venus Nov 14 2026 stations land within 90 minutes of the Horizons
/// hourly grid (test/graha_test.dart).
double? grahaStationJdUt(int body, double nearJdUt, {double windowDays = 3.0}) {
  const double stepDays = 0.125;
  double tLo = nearJdUt - windowDays;
  double rLo = grahaLongitudeRateDegPerDay(body, tLo);
  double? bracketLo;
  double? bracketHi;
  for (double t = tLo + stepDays; t <= nearJdUt + windowDays; t += stepDays) {
    final double r = grahaLongitudeRateDegPerDay(body, t);
    if (rLo == 0.0) return tLo;
    if ((rLo < 0.0 && r > 0.0) || (rLo > 0.0 && r < 0.0)) {
      bracketLo = tLo;
      bracketHi = t;
      break;
    }
    tLo = t;
    rLo = r;
  }
  if (bracketLo == null || bracketHi == null) return null;
  double a = bracketLo;
  double b = bracketHi;
  double fa = grahaLongitudeRateDegPerDay(body, a);
  for (int i = 0; i < 60; i++) {
    final double m = 0.5 * (a + b);
    final double fm = grahaLongitudeRateDegPerDay(body, m);
    if (fm == 0.0) return m;
    if ((fa < 0.0) == (fm < 0.0)) {
      a = m;
      fa = fm;
    } else {
      b = m;
    }
  }
  return 0.5 * (a + b);
}

/// Provisional classical combustion limits - the angular separation
/// from the Sun at or below which a graha is asta (combust). The
/// shastra source decision is still owed (HYA-450 follow-up): these
/// are the commonly printed degrees, kept as data so the choice can be
/// revisited without touching the engine. Earth has no entry and is
/// never combust.
const Map<int, double> kGrahaCombustionLimitsDeg = <int, double>{
  kGrahaMercury: 14.0,
  kGrahaVenus: 10.0,
  kGrahaMars: 17.0,
  kGrahaJupiter: 11.0,
  kGrahaSaturn: 15.0,
};

/// Angular separation between [body] and the Sun at [jdUt], degrees
/// in [0, 180].
double grahaSunSeparationDeg(int body, double jdUt) {
  final double g = grahaPosition(body, jdUt).tropicalLongitudeDeg;
  final double s = sunLongitudeForSeparationDeg(jdTtFromJdUt(jdUt));
  double d = (g - s).abs();
  if (d > 180.0) d = 360.0 - d;
  return d;
}

/// Whether [body] is combust at [jdUt] under the provisional
/// [kGrahaCombustionLimitsDeg].
bool grahaIsCombust(int body, double jdUt) {
  final double? limit = kGrahaCombustionLimitsDeg[body];
  if (limit == null) return false;
  return grahaSunSeparationDeg(body, jdUt) <= limit;
}

/// Mean ascending node (Rahu) tropical longitude at [jdTt], the
/// Meeus eq. 47.7 polynomial. The TRUE node oscillates about +/- 1.6
/// degrees around it and is a display decision parked to PR-B with
/// both publishers; the mean node is the CI-crosschecked channel.
double rahuMeanLongitudeDeg(double jdTt) {
  final double t = (jdTt - 2451545.0) / 36525.0;
  return _norm360(125.04452 -
      1934.136261 * t +
      0.0020708 * t * t +
      t * t * t / 450000.0);
}

/// Mean node (Rahu) sidereal longitude at [jdUt], base ayanamsa
/// profile. Ketu is +180 degrees at the call site.
double rahuMeanSiderealLongitudeDeg(double jdUt) {
  final double jdTt = jdTtFromJdUt(jdUt);
  return _norm360(rahuMeanLongitudeDeg(jdTt) - ayanamsaBase(jdTt));
}

/// Default observer latitude: Kathmandu.
const double kGrahaDefaultLatitude = 27.7172;

/// Default observer longitude east of Greenwich: Kathmandu.
const double kGrahaDefaultLongitude = 85.324;

/// Rise/set horizon: -34 arcmin standard refraction, point-source
/// planets (no semidiameter, parallax negligible at this class).
const double _riseSetHorizonDeg = -0.5667;

/// Mean obliquity of the ecliptic (Meeus 22.2), TT domain.
double _meanObliquityDeg(double jdTt) {
  final double t = (jdTt - 2451545.0) / 36525.0;
  return 23.439291111 -
      0.0130041667 * t -
      1.6388e-7 * t * t +
      5.03611e-7 * t * t * t;
}

/// Greenwich mean sidereal time (Meeus 12.4), degrees, UT domain.
double _gmstDeg(double jdUt) {
  final double t = (jdUt - 2451545.0) / 36525.0;
  return _norm360(280.46061837 +
      360.98564736629 * (jdUt - 2451545.0) +
      0.000387933 * t * t -
      t * t * t / 38710000.0);
}

/// Geometric altitude of [body] above the horizon at [jdUt], degrees
/// (apparent place of date through the mean obliquity; consistent
/// with the no-nutation pipeline).
double _altitudeDeg(
    double jdUt, int body, double latitudeDeg, double longitudeDeg) {
  final pos = grahaPosition(body, jdUt);
  final double eps =
      _meanObliquityDeg(jdTtFromJdUt(jdUt)) * _radPerDeg;
  final double lon = pos.tropicalLongitudeDeg * _radPerDeg;
  final double lat = pos.tropicalLatitudeDeg * _radPerDeg;
  final double dec = math.asin(
      math.sin(lat) * math.cos(eps) + math.cos(lat) * math.sin(eps) * math.sin(lon));
  final double ra = math.atan2(
      math.sin(lon) * math.cos(eps) - math.tan(lat) * math.sin(eps),
      math.cos(lon));
  double hourAngle =
      (_gmstDeg(jdUt) + longitudeDeg - ra * _degPerRad) % 360.0;
  if (hourAngle > 180.0) hourAngle -= 360.0;
  if (hourAngle < -180.0) hourAngle += 360.0;
  final double phi = latitudeDeg * _radPerDeg;
  final double sinAlt = math.sin(phi) * math.sin(dec) +
      math.cos(phi) * math.cos(dec) * math.cos(hourAngle * _radPerDeg);
  return math.asin(sinAlt) * _degPerRad;
}

/// Scan the NPT civil day [00:00, 24:00) in 30-minute steps for the
/// first horizon crossing (rise or set), then 40 bisections. A planet
/// crosses the horizon exactly once per 24 hours, so the coarse scan
/// cannot skip an event; circumpolar days return null naturally.
double? _grahaCrossingJdUt({
  required int body,
  required int year,
  required int month,
  required int day,
  required bool rising,
  double latitude = kGrahaDefaultLatitude,
  double longitude = kGrahaDefaultLongitude,
}) {
  final double jdStartUt = julianDayFromCivil(year, month, day.toDouble()) -
      nptOffsetHours / 24.0;
  double f(double jd) =>
      _altitudeDeg(jd, body, latitude, longitude) - _riseSetHorizonDeg;
  double tPrev = jdStartUt;
  double fPrev = f(tPrev);
  for (int i = 1; i <= 48; i++) {
    final double t = jdStartUt + i / 48.0;
    final double fv = f(t);
    if (rising ? (fPrev < 0.0 && fv >= 0.0) : (fPrev > 0.0 && fv <= 0.0)) {
      double a = tPrev;
      double b = t;
      for (int k = 0; k < 40; k++) {
        final double m = 0.5 * (a + b);
        if ((f(m) < 0.0) == (fPrev < 0.0)) {
          a = m;
        } else {
          b = m;
        }
      }
      return 0.5 * (a + b);
    }
    tPrev = t;
    fPrev = fv;
  }
  return null;
}

/// Rise instant of [body] on the NPT civil day, UT Julian Day, or
/// null if it never crosses the horizon upward that day. Kathmandu
/// defaults mirror the sunrise/moonrise solvers.
double? grahaRiseJdUt({
  required int year,
  required int month,
  required int day,
  required int body,
  double latitude = kGrahaDefaultLatitude,
  double longitude = kGrahaDefaultLongitude,
}) =>
    _grahaCrossingJdUt(
        body: body,
        year: year,
        month: month,
        day: day,
        rising: true,
        latitude: latitude,
        longitude: longitude);

/// Set instant of [body] on the NPT civil day (the setting twin).
double? grahaSetJdUt({
  required int year,
  required int month,
  required int day,
  required int body,
  double latitude = kGrahaDefaultLatitude,
  double longitude = kGrahaDefaultLongitude,
}) =>
    _grahaCrossingJdUt(
        body: body,
        year: year,
        month: month,
        day: day,
        rising: false,
        latitude: latitude,
        longitude: longitude);
